commit 9b219c90d79071c4b7bb84f81d17be0cdd885d71
Author: 佐藤圭吾 <k0127s@gmail.com>
Date:   Sun Aug 2 16:53:05 2026 +0900

    fix: story diagnose の全ディレクトリwalkerを反復処理化し spread起因の Maximum call stack size exceeded を解消

    diagnosis 生成パス上の8 scanner walkerが files.push(...await walk(...)) で
    サブツリー全件をspread引数として渡しており、大規模repo（実測134k files、
    .claude/worktrees配下127k）でV8の引数上限を超えてクラッシュしていた。
    全walkerを明示キュー＋単一アキュムレータの反復走査へ書き換え（走査結果は不変）。
    回帰テストは --stack-size=200 の子プロセスで30k filesを走査し、旧実装のfailを
    スケールダウン再現して固定する。

    story: story-vibepro-profiler-file-walk-stack-overflow

    Co-Authored-By: Claude Fable 5 <noreply@anthropic.com>

diff --git a/src/network-contract-scanner.js b/src/network-contract-scanner.js
index abd3aab1..d9180425 100644
--- a/src/network-contract-scanner.js
+++ b/src/network-contract-scanner.js
@@ -368,14 +368,19 @@ async function listRepoFiles(root) {
   return filesystemFiles;
 }

-async function listFilesRecursive(root, dir = root) {
-  const entries = await readdir(dir, { withFileTypes: true });
+async function listFilesRecursive(root) {
+  // Iterative walk with a single accumulator: recursion + spread-push overflows
+  // the call stack once a subtree holds more entries than V8 accepts as arguments.
   const files = [];
-  for (const entry of entries) {
-    if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.vibepro') continue;
-    const fullPath = path.join(dir, entry.name);
-    if (entry.isDirectory()) files.push(...await listFilesRecursive(root, fullPath));
-    else files.push(normalizePath(path.relative(root, fullPath)));
+  const pending = [root];
+  for (let index = 0; index < pending.length; index += 1) {
+    const entries = await readdir(pending[index], { withFileTypes: true });
+    for (const entry of entries) {
+      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.vibepro') continue;
+      const fullPath = path.join(pending[index], entry.name);
+      if (entry.isDirectory()) pending.push(fullPath);
+      else files.push(normalizePath(path.relative(root, fullPath)));
+    }
   }
   return files;
 }

